package quads

import (
	"path/filepath"
	"testing"

	"github.com/qmuntal/gltf"
)

// The torch is generated by tools/gentorch, so this is the check that the generator
// and the loader still agree: six quads, nothing else, and the box standing on the
// floor rather than centred on it.
func TestTorchModelIsSixQuads(t *testing.T) {
	mesh := LoadGLTF(filepath.Join("..", "assets", "meshes", "torch.glb"), nil, nil)
	if mesh == nil {
		t.Fatal("torch.glb did not load - re-run: go run ./tools/gentorch")
	}

	if got := mesh.TriangleCount(); got != 12 {
		t.Errorf("triangles: got %d want 12 (6 quads, 2 triangles each)", got)
	}

	doc, err := gltf.Open(filepath.Join("..", "assets", "meshes", "torch.glb"))
	if err != nil {
		t.Fatal(err)
	}
	if got := len(doc.Meshes[0].Primitives); got != 1 {
		t.Fatalf("primitives: got %d want 1", got)
	}
	primitive := doc.Meshes[0].Primitives[0]
	if got := doc.Accessors[primitive.Attributes[gltf.POSITION]].Count; got != 24 {
		t.Errorf("vertices: got %d want 24 (6 quads, 4 corners each, no corner shared)", got)
	}
	if got := doc.Accessors[*primitive.Indices].Count; got != 36 {
		t.Errorf("indices: got %d want 36", got)
	}
	// The texture rides in the .glb: the mesh loader reads it off the buffer view,
	// and a side-car PNG would have to be found relative to the working directory.
	if len(doc.Images) != 1 || doc.Images[0].BufferView == nil {
		t.Errorf("the torch texture is not embedded in the .glb")
	}

	min, max := mesh.FindBounds()
	if min.Y() != 0 {
		t.Errorf("the torch does not stand on its origin: lowest Y is %v", min.Y())
	}
	if height := max.Y() - min.Y(); height < 0.6 || height > 0.65 {
		t.Errorf("height: got %v want ~0.625", height)
	}
	if width := max.X() - min.X(); width < 0.1 || width > 0.15 {
		t.Errorf("width: got %v want ~0.125", width)
	}
}
